coding.solution:
import math

def _norm(v):
    return math.sqrt(sum(x * x for x in v))

def top_k(query, vectors, k):
    qn = _norm(query)
    scored = []
    for vid, v in vectors.items():
        vn = _norm(v)
        if vn == 0 or qn == 0:
            continue
        cos = sum(a * b for a, b in zip(query, v)) / (qn * vn)
        scored.append((-cos, vid))
    scored.sort()
    return [vid for _, vid in scored[:k]]

def recall_at_k(exact, approx, k):
    if not exact:
        return 0.0
    total = 0.0
    for e, a in zip(exact, approx):
        total += len(set(e[:k]) & set(a[:k])) / k
    return round(total / len(exact), 3)

