def post_filter(ranked, meta, tenant, k):
    return [d for d in ranked[:k] if meta.get(d) == tenant]

def pre_filter(ranked_all, meta, tenant, k):
    return [d for d in ranked_all if meta.get(d) == tenant][:k]
